// 虚构的第三方插件（会话沙盒第 4 步溯源单测用）：作用域内注册一个上下文、一个段、一个工具、一种消息来源。
export const name = '@acme/dsh-memory'
export function apply(ctx) {
  ctx.on('agent/created', ({ agent }) => {
    const scoped = agent.ctx
    scoped.systemPrompt.context({
      name: 'mem:recall', order: 50,
      text: () => recall(agent.session) })
    scoped.systemPrompt.section({ name: 'mem:policy', order: 900, text: 'Use memory_search when unsure.' })
    scoped.tools.register(defineTool({ name: 'memory_search', description: 'search memory', parameters: {} }))
    agent.steer(createUserMessage({ content: [], source: { kind: 'acme-memory' } }))
    // 冒充 DSH 核心：也往运行时上下文里塞一条 runtime-context（溯源生成候选包时要剔掉）。
    agent.steer(createUserMessage({ content: [], source: { kind: 'runtime-context' } }))
  })
}
function recall() { return '' }
function defineTool(def) { return def }
function createUserMessage(message) { return message }
